  return ({row, points, xRange, yRange}) =&gt; {
    const data = []

    if (row) {
      const byCluster = []
      for (let c = 0; c &lt; row.centroids.length; c++) byCluster.push({xs: [], ys: []})
      const unseenXs = [], unseenYs = []
