    }
    if (showEMA && rows.length &gt; 0) {
      const ys = []
      for (const row of rows) ys.push(row.emaVal)
      traces.push({x: xs, y: ys, type: "scatter", mode: "lines", name: "Exponential Moving Average", showlegend: false, line: {color: "#16a34a", width: 2.5}})
    }
    if (showKalman && rows.length &gt; 0) {
      const ys = []
      for (const row of rows) ys.push(row.kalmanVal)
      traces.push({x: xs, y: ys, type: "scatter", mode: "lines+markers", name: "Kalman Filter", showlegend: false, line: {color: "#dc2626", width: 2.5}, marker: {color: "#dc2626", size: 5}})
    }

