    return null
  }
  return Plot.plot({
    width: 340, height: 300, marginLeft: 46,
    x: {label: "n"},
    y: {label: "xₙ"},
    marks: [
      Plot.lineY(result.rows, {x: "i", y: xAccessor, stroke: "#2563eb"}),
      Plot.dot(result.rows, {x: "i", y: xAccessor, fill: "#2563eb", r: 4})
